export class CustomerDao {
  #pool;                                    // injected pg.Pool, never created here
  constructor(pool) { this.#pool = pool; }
  async find(id) {
    const { rows } = await this.#pool.query(
      'SELECT id, name, version FROM customer WHERE id = $1', [id]);
    return rows[0] ?? null;                 // plain row object, not a cursor
  }
  async add({ id, name }) {
    await this.#pool.query('INSERT INTO customer (id, name) VALUES ($1, $2)', [id, name]);
  }
}
